css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .figuras-eje{display: grid; grid-template-columns: repeat(5, 1fr); gap: 9px;}
.mz .fig-caja{border: 1px solid #999; border-radius: 8px; padding: 14px 4px; display: flex; align-items: center; justify-content: center;}
.mz .fig-caja svg{width: 112px; height: 112px;}
.mz .letras-grid{display: grid; grid-template-columns: repeat(8, 1fr); gap: 8px;}
.mz .letra-caja{border: 1.5px dashed #000; border-radius: 8px; height: 100px; display: flex; align-items: center; justify-content: center; font-family: Arial, Helvetica, sans-serif; font-weight: 800; font-size: 40px;}
.mz .simetricas-grid{display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px;}
.mz .sim-caja{border: 1.5px dashed #000; border-radius: 8px; padding: 10px 3px; display: flex; align-items: center; justify-content: center;}
.mz .sim-caja svg{width: 102px; height: 102px;}
.mz .espejo-fila{display: flex; gap: 80px; justify-content: center; align-items: flex-start; padding-top: 2px;}
.mz .vf-item{display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; margin-bottom: 21px;}
.mz .vf-ops{margin-left: auto; display: flex; gap: 14px; flex-shrink: 0;}
.mz .vf-circ{width: 32px; height: 32px; border: 1.5px solid var(--bosque); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: sans-serif; font-weight: 700; font-size: 15px;}
